// Where the key comes from decides whether any of this works.
//
// A key names an INTENT — this one order, this one payment — not a delivery. Two deliveries of the same
// intent must produce the same key, and a new intent must never reuse one. Generating a key here
// (crypto.randomUUID(), Date.now(), $execution.id) makes every delivery unique and silently turns the
// whole gate into a no-op, which is the usual way this pattern is got wrong.
//
// Preferred source is the caller's Idempotency-Key header (the convention Stripe, Square and friends
// follow); a stable business id in the body is the fallback. n8n lowercases incoming header names.
const req = $input.first().json;
const headers = req.headers ?? {};
const body = req.body ?? {};

const raw = headers['idempotency-key'] ?? headers['x-idempotency-key'] ?? body.idempotencyKey ?? body.orderId ?? null;
// An object or array would stringify to '[object Object]' and collapse every such caller into one
// ledger row — one shared key, so the first one through blocks all the others.
if (raw !== null && raw !== undefined && typeof raw !== 'string' && typeof raw !== 'number') {
  throw new Error(`idempotency key must be a string or a number, got ${typeof raw}`);
}
const key = raw === null || raw === undefined ? '' : String(raw).trim();

// Refusing the work is the only safe answer: without a key this endpoint cannot tell a retry from a
// second order, and guessing either way is a lost order or a double charge.
if (key === '') {
  throw new Error('no idempotency key: send an Idempotency-Key header or an orderId in the body');
}
// Rejected, never truncated: two keys that differ only after the cut would collide, and a collision
// here means one caller's work is silently skipped as somebody else's duplicate.
if (key.length > 200) {
  throw new Error(`idempotency key is ${key.length} characters, the limit is 200`);
}

return [{ json: { key, owner: `exec:${$execution.id}`, payload: body } }];

// The ledger write is the only thing standing between "the work happened" and "a replay is told it
// happened". If it did not land, say so loudly rather than answer 200: the caller gets a 500 and
// retries, and the retry reads the ledger instead of redoing the work.
const row = $input.first().json;
const key = $('Idempotency key').item.json.key;

if (row.state !== 'done') {
  throw new Error(`the work ran but the ledger row for ${key} was not completed — reconcile by hand`);
}

return [{ json: { outcome: 'done', key, result: $('Do the work').item.json } }];

// Everything that is not a fresh claim lands here. Three different situations, three different answers,
// and the difference between them is the point of the template.
const row = $input.first().json;
const key = $('Idempotency key').item.json.key;

if (row.route === 'replay') {
  // The first execution finished. Answer exactly what it answered and do nothing else — that is what
  // makes this endpoint safe to retry.
  return [{ json: { outcome: 'duplicate', key, result: row.result ?? null } }];
}

if (row.route === 'in_flight') {
  // Another execution holds the lease and is still inside it. Throwing is deliberate: the caller gets a
  // 500, retries, and by then the key is 'done' and the retry gets the stored result. Answering 200 here
  // would tell the caller that work succeeded which may still fail.
  throw new Error(`key ${key} is in flight (held by ${row.lease_owner} for ${row.age_seconds}s) — retry`);
}

// route === 'stale': the lease holder claimed the key and never completed it, which is what a killed
// worker leaves behind — n8n 2.x does not retry in-flight executions, and a crashed one may already have
// done its side effect (docs/operations/chaos-drills.md). Whether the work happened is not knowable from
// here, so nothing decides it automatically: this raises, the Error Workflow alerts, a human reconciles.
throw new Error(
  `key ${key} was claimed ${row.age_seconds}s ago by ${row.lease_owner} and never completed — the work ` +
    'may or may not have happened; reconcile it by hand, then delete the row to allow a retry',
);
